// @FIGURE_CODE_BEGIN
(function () {
  var container = document.getElementById('container');
  var canvas = document.createElement('canvas');
  canvas.style.width = '100%'; canvas.style.height = '100%'; canvas.style.display = 'block';
  container.appendChild(canvas);

  // ── State: y = a(x − h)² + k ──────────────────────────────────────────
  var S = { h: 1, k: -4, a: 1, mode: 'all' }; // mode: all | intercepts | symmetry
  var D = 6; // axis range
  var chart = null; // assigned after construction; plugin draws must guard on it

  function f(x) { return S.a * (x - S.h) * (x - S.h) + S.k; }
  function disc() { return -S.k / S.a; } // >0 → two x-intercepts
  function xInts() {
    var d = disc();
    if (d < 0) return [];
    var r = Math.sqrt(d);
    return [S.h - r, S.h + r];
  }

  function dim(alpha) { return 'rgba(60,60,60,' + alpha + ')'; }
  function emph(kind) { // kind: 'intercepts' | 'symmetry'
    if (S.mode === 'all') return 1;
    return S.mode === kind ? 1 : 0.22;
  }

  // ── Datasets ──────────────────────────────────────────────────────────
  function curveData() {
    var pts = [];
    for (var x = -6; x <= 6.001; x += 0.05) {
      var y = f(x);
      if (y <= 6.6 && y >= -6.6) pts.push({ x: x, y: y });
    }
    return pts;
  }
  function axisData() { return [{ x: S.h, y: -6 }, { x: S.h, y: 6 }]; }
  function pt(x, y) { return [{ x: x, y: y }]; }

  function getDs(id) {
    if (!chart || !chart.data || !chart.data.datasets) return null;
    for (var i = 0; i < chart.data.datasets.length; i++) {
      if (chart.data.datasets[i].id === id) return chart.data.datasets[i];
    }
    return null;
  }

  function px(v) { return chart.scales.x.getPixelForValue(v); }
  function py(v) { return chart.scales.y.getPixelForValue(v); }

  // Halo text so labels stay readable over gridlines/curve
  function label(ctx, text, x, y, alpha, color, align) {
    ctx.save();
    ctx.globalAlpha = alpha;
    ctx.font = 'italic 13px Georgia, serif';
    ctx.textAlign = align || 'left';
    ctx.textBaseline = 'middle';
    ctx.lineWidth = 3.5; ctx.strokeStyle = '#fff'; ctx.lineJoin = 'round';
    ctx.strokeText(text, x, y);
    ctx.fillStyle = color || '#000';
    ctx.fillText(text, x, y);
    ctx.restore();
  }

  function leader(ctx, x1, y1, x2, y2, alpha) {
    ctx.save();
    ctx.globalAlpha = alpha;
    ctx.strokeStyle = '#444'; ctx.lineWidth = 1;
    ctx.beginPath(); ctx.moveTo(x1, y1); ctx.lineTo(x2, y2); ctx.stroke();
    var ang = Math.atan2(y2 - y1, x2 - x1), L = 6;
    ctx.beginPath();
    ctx.moveTo(x2, y2);
    ctx.lineTo(x2 - L * Math.cos(ang - 0.4), y2 - L * Math.sin(ang - 0.4));
    ctx.lineTo(x2 - L * Math.cos(ang + 0.4), y2 - L * Math.sin(ang + 0.4));
    ctx.closePath(); ctx.fillStyle = '#444'; ctx.fill();
    ctx.restore();
  }

  function rnd(v) { return Math.round(v * 100) / 100; }

  // ── Annotation plugin ─────────────────────────────────────────────────
  // Chart.js may invoke plugins during construction, before the outer `chart`
  // variable is assigned. Guard every access and use the plugin's own chart
  // argument `c` (c.data, c.scales) — never the outer variable here.
  function drawAnnotations(c) {
    if (!c || !c.scales || !c.scales.x || !c.scales.y || !c.chartArea) return;
    if (!c.data || !c.data.datasets) return;
    var ctx = c.ctx;
    if (!ctx) return;

    var area = c.chartArea;
    var xi = xInts(), yv = f(0), mirrorX = 2 * S.h;
    var symA = emph('symmetry'), intA = emph('intercepts');

    function lpx(v) { return c.scales.x.getPixelForValue(v); }
    function lpy(v) { return c.scales.y.getPixelForValue(v); }

    // Arrowheads on branch tops
    var cds = null;
    for (var i = 0; i < c.data.datasets.length; i++) {
      if (c.data.datasets[i].id === 'curve') cds = c.data.datasets[i];
    }
    var cd = cds && cds.data ? cds.data : [];
    if (cd.length > 1) {
      ctx.save();
      ctx.fillStyle = '#0e7c86';
      [[cd[0], cd[1]], [cd[cd.length - 1], cd[cd.length - 2]]].forEach(function (pr) {
        var p = pr[0], q = pr[1];
        var X = lpx(p.x), Y = lpy(p.y), X2 = lpx(q.x), Y2 = lpy(q.y);
        var ang = Math.atan2(Y - Y2, X - X2), L = 9;
        ctx.beginPath();
        ctx.moveTo(X, Y);
        ctx.lineTo(X - L * Math.cos(ang - 0.35), Y - L * Math.sin(ang - 0.35));
        ctx.lineTo(X - L * Math.cos(ang + 0.35), Y - L * Math.sin(ang + 0.35));
        ctx.closePath(); ctx.fill();
      });
      ctx.restore();
    }

    var vx = lpx(S.h), vy = lpy(S.k);

    // Axis of symmetry label (top, right of dashed line)
    var axX = Math.min(vx + 14, area.right - 118);
    label(ctx, 'Axis of symmetry', axX, area.top + 14, symA, '#b01818');
    leader(ctx, axX + 6, area.top + 24, vx + 3, lpy(2), symA);

    // Vertex label (lower right)
    var vlx = Math.min(vx + 30, area.right - 60), vly = Math.min(vy + 26, area.bottom - 10);
    label(ctx, 'Vertex', vlx, vly, symA);
    leader(ctx, vlx - 4, vly - 8, vx + 6, vy + 3, symA);

    // x-intercepts label
    if (xi.length) {
      var lx = lpx(Math.max(xi[0], xi[1])) + 16, ly = lpy(1.1);
      if (lx > area.right - 90) lx = area.right - 90;
      label(ctx, 'x-intercepts', lx, ly, intA);
      leader(ctx, lx + 4, ly + 8, lpx(xi[1]) - 4, lpy(0) - 4, intA);
      leader(ctx, lx - 6, ly + 10, lpx(xi[0]) + 4, lpy(0) - 5, intA);
    } else {
      label(ctx, 'x-intercepts: none (a·k > 0)', lpx(-5.6), lpy(1.1), intA);
    }

    // y-intercept label (lower left)
    if (yv >= -6 && yv <= 6) {
      var ylx = area.left + 8, yly = Math.min(lpy(yv) + 26, area.bottom - 8);
      label(ctx, 'y-intercept', ylx, yly, intA);
      leader(ctx, ylx + 40, yly - 8, lpx(0) - 4, lpy(yv) + 3, intA);
    }

    // Symmetry pair guide: dashed horizontal link y-int ↔ mirror (symmetry mode)
    if (S.mode === 'symmetry' && yv >= -6 && yv <= 6) {
      ctx.save();
      ctx.strokeStyle = 'rgba(180,24,24,0.7)'; ctx.setLineDash([3, 3]); ctx.lineWidth = 1;
      ctx.beginPath(); ctx.moveTo(lpx(0), lpy(yv)); ctx.lineTo(lpx(mirrorX), lpy(yv)); ctx.stroke();
      ctx.setLineDash([]);
      ctx.restore();
      label(ctx, 'equal heights, equally far from x = ' + rnd(S.h),
        (lpx(0) + lpx(mirrorX)) / 2, lpy(yv) - 12, 1, '#b01818', 'center');
    }

    // Equation readout, top-left inside plot
    label(ctx, 'y = ' + rnd(S.a) + '(x − ' + rnd(S.h) + ')² ' + (S.k < 0 ? '− ' + rnd(-S.k) : '+ ' + rnd(S.k)),
      area.left + 6, area.top + 6, 1, '#0e5c64');
  }

  chart = new Chart(canvas.getContext('2d'), {
    type: 'line',
    data: {
      datasets: [
        { id: 'curve', data: curveData(), borderColor: '#0e7c86', borderWidth: 3, pointRadius: 0, showLine: true, fill: false },
        { id: 'axis', data: axisData(), borderColor: '#d02020', borderWidth: 2, borderDash: [7, 5], pointRadius: 0, showLine: true },
        { id: 'vertex', type: 'scatter', data: pt(S.h, S.k), backgroundColor: '#000', pointRadius: 5, pointHoverRadius: 7 },
        { id: 'xints', type: 'scatter', data: [], backgroundColor: '#000', pointRadius: 5 },
        { id: 'yint', type: 'scatter', data: [], backgroundColor: '#000', pointRadius: 5 },
        { id: 'mirror', type: 'scatter', data: [], backgroundColor: '#000', pointRadius: 5 }
      ]
    },
    options: {
      responsive: true, maintainAspectRatio: false, animation: false,
      events: [], // we handle pointer interaction ourselves
      plugins: { legend: { display: false }, tooltip: { enabled: false } },
      scales: {
        x: {
          type: 'linear', min: -D, max: D,
          grid: { color: 'rgba(150,150,150,0.55)', borderDash: [2, 3], drawTicks: true },
          ticks: { stepSize: 2, font: { size: 11 }, color: '#222' },
          title: { display: true, text: 'x', font: { size: 15, style: 'italic' }, color: '#000' },
          border: { color: '#000', width: 1.5 }
        },
        y: {
          min: -D, max: D,
          grid: { color: 'rgba(150,150,150,0.55)', borderDash: [2, 3] },
          ticks: { stepSize: 2, font: { size: 11 }, color: '#222' },
          title: { display: true, text: 'y', font: { size: 15, style: 'italic' }, color: '#000' },
          border: { color: '#000', width: 1.5 }
        }
      }
    },
    plugins: [{
      id: 'annotate',
      afterDraw: function (c) { drawAnnotations(c); }
    }]
  });

  function refresh() {
    if (!chart) return;
    var d;
    d = getDs('curve'); if (d) d.data = curveData();
    d = getDs('axis');
    if (d) {
      d.data = axisData();
      d.borderColor = 'rgba(208,32,32,' + (0.35 + 0.65 * emph('symmetry')) + ')';
    }
    d = getDs('vertex');
    if (d) { d.data = pt(S.h, S.k); d.backgroundColor = dim(0.25 + 0.75 * emph('symmetry')); }
    var xi = xInts();
    d = getDs('xints');
    if (d) {
      d.data = xi.map(function (x) { return { x: x, y: 0 }; });
      d.backgroundColor = dim(0.25 + 0.75 * emph('intercepts'));
    }
    var yv = f(0);
    d = getDs('yint');
    if (d) {
      d.data = (yv >= -6 && yv <= 6) ? pt(0, yv) : [];
      d.backgroundColor = dim(0.25 + 0.75 * emph('intercepts'));
    }
    d = getDs('mirror');
    if (d) {
      d.data = (yv >= -6 && yv <= 6) ? pt(2 * S.h, yv) : [];
      d.backgroundColor = dim(0.25 + 0.75 * emph('symmetry'));
    }
    chart.update();
  }

  // ── Vertex dragging ───────────────────────────────────────────────────
  var dragging = false;
  function evtPos(e) {
    var r = canvas.getBoundingClientRect();
    var t = (e.touches && e.touches[0]) || e;
    return { x: t.clientX - r.left, y: t.clientY - r.top };
  }
  function nearVertex(p) {
    if (!chart || !chart.scales || !chart.scales.x) return false;
    return Math.abs(p.x - px(S.h)) < 16 && Math.abs(p.y - py(S.k)) < 16;
  }
  canvas.style.cursor = 'pointer';
  function down(e) { var p = evtPos(e); if (nearVertex(p)) { dragging = true; e.preventDefault(); } }
  function move(e) {
    if (!chart || !chart.scales || !chart.scales.x) return;
    var p = evtPos(e);
    if (!dragging) { canvas.style.cursor = nearVertex(p) ? 'grab' : 'default'; return; }
    canvas.style.cursor = 'grabbing';
    var wx = chart.scales.x.getValueForPixel(p.x);
    var wy = chart.scales.y.getValueForPixel(p.y);
    S.h = Math.max(-5, Math.min(5, Math.round(wx * 2) / 2));
    S.k = Math.max(-5.5, Math.min(4, Math.round(wy * 2) / 2));
    refresh(); e.preventDefault();
  }
  function up() {
    if (dragging) {
      dragging = false;
      showPopup('Vertex moved', 'The whole parabola followed: the axis of symmetry is now x = ' + rnd(S.h) +
        ', and every feature slid with it. The vertex alone fixes the symmetry line.');
    }
  }
  canvas.addEventListener('mousedown', down);
  window.addEventListener('mousemove', move);
  window.addEventListener('mouseup', up);
  canvas.addEventListener('touchstart', down, { passive: false });
  canvas.addEventListener('touchmove', move, { passive: false });
  window.addEventListener('touchend', up);

  // ── Controls ──────────────────────────────────────────────────────────
  window.update_verticalStretch = function (v) {
    S.a = v; refresh();
  };
  window.toggle_featureHighlight = function (val) {
    S.mode = val; refresh();
  };

  // ── Demo steps ────────────────────────────────────────────────────────
  var steps = [
    { title: 'Read the features', a: 1, mode: 'all', h: 1, k: -4,
      text: 'The parabola y = (x − 1)² − 4 shows all key features at once: vertex (1, −4), axis x = 1, x-intercepts −1 and 3, y-intercept −3 and its mirror point (2, −3).' },
    { title: 'Check the symmetry', a: 1, mode: 'symmetry', h: 1, k: -4,
      text: 'The y-intercept and its mirror point sit at equal heights on opposite sides of the dashed line, equally far from x = 1 — the defining test of the axis of symmetry.' },
    { title: 'Drag the vertex', a: 1, mode: 'symmetry', h: 1, k: -4,
      text: 'Now drag the vertex dot: the dashed axis, both intercepts, and the mirror pair all travel with it — the vertex alone determines where the symmetry line lies.' },
    { title: 'Stretch the parabola', a: 2.5, mode: 'intercepts', h: 1, k: -4,
      text: 'With a = 2.5 the branches steepen and the x-intercepts pull inward toward the axis. Slide a down and they spread apart — vertex and axis never move.' }
  ];
  var stepIdx = 0;
  function setStep(i) {
    stepIdx = Math.max(0, Math.min(steps.length - 1, i));
    var st = steps[stepIdx];
    S.a = st.a; S.mode = st.mode; S.h = st.h; S.k = st.k;
    document.getElementById('verticalStretchInput').value = st.a;
    document.getElementById('verticalStretchVal').value = st.a;
    document.getElementById('featureHighlightInput').value = st.mode;
    document.getElementById('demoNarration').textContent = st.text;
    document.getElementById('stepLabel').textContent = (stepIdx + 1) + ' / ' + steps.length;
    refresh();
  }
  window.nextStep = function () { setStep(stepIdx + 1); };
  window.prevStep = function () { setStep(stepIdx - 1); };

  document.addEventListener('fig-resize', function () { if (chart) chart.resize(); });

  setStep(0);
  window.__markRendered();
})();
// @FIGURE_CODE_END

